import{_ as r,o as a,c as l,a as o}from"./chunks/framework.Ld7uezS_.js";const u=JSON.parse('{"title":"理论只读训练","description":"","frontmatter":{},"headers":[],"relativePath":"training-theory.md","filePath":"training-theory.md","lastUpdated":1787280255000}'),e={name:"training-theory.md"};function i(n,t,s,h,d,g){return a(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="理论只读训练" tabindex="-1">理论只读训练 <a class="header-anchor" href="#理论只读训练" aria-label="Permalink to &quot;理论只读训练&quot;">​</a></h1><blockquote><p><strong>只读训练：答案与解析已展开，无需作答或提交。</strong></p></blockquote><h2 id="十个理论模块覆盖表" tabindex="-1">十个理论模块覆盖表 <a class="header-anchor" href="#十个理论模块覆盖表" aria-label="Permalink to &quot;十个理论模块覆盖表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th style="text-align:right;">当前题卡</th><th>覆盖主题</th><th>知识页</th></tr></thead><tbody><tr><td>1. 职业道德</td><td style="text-align:right;">T01、T15、T28</td><td>方针、原则、职业守则、如实记录和复核</td><td><a href="/theory/01-professional-ethics">进入</a></td></tr><tr><td>2. 消防工作概述</td><td style="text-align:right;">T02、T16、T29</td><td>单位责任、岗位边界、报警处置和异常报告</td><td><a href="/theory/02-fire-service-overview">进入</a></td></tr><tr><td>3. 燃烧和火灾</td><td style="text-align:right;">T03-T04、T30</td><td>燃烧条件、火灾分类、灭火禁忌和电气火灾场景</td><td><a href="/theory/03-combustion-fire">进入</a></td></tr><tr><td>4. 建筑防火</td><td style="text-align:right;">T20-T21、T31、T38-T39</td><td>防火分区、防烟分区、防火间距、耐火极限、耐火等级、疏散、救援条件和卷帘安全</td><td><a href="/theory/04-building-fire">进入</a></td></tr><tr><td>5. 电气消防</td><td style="text-align:right;">T06、T22、T32</td><td>交直流、消防电源、验电、保护和蓄电池维修边界</td><td><a href="/theory/05-electrical-fire">进入</a></td></tr><tr><td>6. 消防设施</td><td style="text-align:right;">T08-T10、T23-T24、T33</td><td>信号链、组件功能、反馈、恢复和联动排查</td><td><a href="/theory/06-fire-facilities">进入</a></td></tr><tr><td>7. 初起火灾处置</td><td style="text-align:right;">T07、T11、T17、T34</td><td>带电设备、烟气、撤退条件、复燃与现场保护</td><td><a href="/theory/07-initial-fire">进入</a></td></tr><tr><td>8. 计算机基础</td><td style="text-align:right;">T13、T18、T25、T35</td><td>值班记录、显示链路、权限、日志和信息安全</td><td><a href="/theory/08-computer">进入</a></td></tr><tr><td>9. 法律法规与技术标准</td><td style="text-align:right;">T05、T12、T26、T36</td><td>规范层级、责任主体、版本核验和参数适用边界</td><td><a href="/theory/09-laws-standards">进入</a></td></tr><tr><td>10. 安全生产与职业健康</td><td style="text-align:right;">T14、T19、T27、T37</td><td>断电、验电、隔离、监护、特殊作业和清场</td><td><a href="/theory/10-safety-health">进入</a></td></tr></tbody></table><blockquote><p>当前题卡按学习主题组织，均为本站原创只读训练题，不是官方真题。每章现已至少包含基础识记、条件辨析或综合场景中的多种训练层级；题量仍不等于实际考试题库，表格中的编号用于透明展示学习覆盖范围，后续增加题目时必须同步更新。</p></blockquote><p>理论训练按“概念识记 → 条件辨析 → 场景应用”递进。先看答案，再读解析，最后回到知识页补原理。</p><h2 id="_1-职业道德与消防工作" tabindex="-1">1. 职业道德与消防工作 <a class="header-anchor" href="#_1-职业道德与消防工作" aria-label="Permalink to &quot;1. 职业道德与消防工作&quot;">​</a></h2><h3 id="题卡-t01-·-判断题-·-l1-·-原创训练题" tabindex="-1">题卡 T01 · 判断题 · L1 · 原创训练题 <a class="header-anchor" href="#题卡-t01-·-判断题-·-l1-·-原创训练题" aria-label="Permalink to &quot;题卡 T01 · 判断题 · L1 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：消防工作方针是“预防为主，防消结合”。</p><p><strong>答案</strong>：正确。</p><p><strong>解析</strong>：这是消防工作的方针，回答消防工作的总方向。不要把它与“政府统一领导、部门依法监管、单位全面负责、公民积极参与”这一消防工作原则混淆。</p><p><strong>核心知识点</strong>：方针与原则的区别。</p><p><strong>依据</strong>：<a href="/sources">消防设施操作员国家职业技能标准（2019年版）</a>；<a href="/theory/02-fire-service-overview">消防工作概述</a>。</p><h3 id="题卡-t02-·-单选题-·-l2-·-原创训练题" tabindex="-1">题卡 T02 · 单选题 · L2 · 原创训练题 <a class="header-anchor" href="#题卡-t02-·-单选题-·-l2-·-原创训练题" aria-label="Permalink to &quot;题卡 T02 · 单选题 · L2 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：消防控制室发现控制器显示火灾报警，但现场暂未看到明火，首先不应采取的做法是：</p><ul><li>A. 记录地址、时间和报警类别</li><li>B. 按预案核实现场并报告</li><li>C. 直接复位，确认声音停止后继续值班</li><li>D. 根据现场安全情况组织相关人员处置</li></ul><p><strong>答案</strong>：C。</p><p><strong>解析</strong>：没有看到明火不等于没有火灾。复位只能改变设备状态，不能证明报警原因已经排除。应先记录、核实、报告，满足条件后再按程序复位并确认系统恢复。</p><p><strong>易错点</strong>：把“消音/复位”当成“排除故障或排除火警”。</p><p><strong>关联</strong>：<a href="/skill/01-monitoring">设施监控</a>、<a href="/beginner-guide">零基础导学</a>。</p><h2 id="_2-燃烧和火灾" tabindex="-1">2. 燃烧和火灾 <a class="header-anchor" href="#_2-燃烧和火灾" aria-label="Permalink to &quot;2. 燃烧和火灾&quot;">​</a></h2><h3 id="题卡-t03-·-多选题-·-l1-·-原创训练题" tabindex="-1">题卡 T03 · 多选题 · L1 · 原创训练题 <a class="header-anchor" href="#题卡-t03-·-多选题-·-l1-·-原创训练题" aria-label="Permalink to &quot;题卡 T03 · 多选题 · L1 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：燃烧通常需要哪些基本条件？</p><ul><li>A. 可燃物</li><li>B. 氧化剂/助燃物</li><li>C. 引火源或达到着火条件的能量</li><li>D. 必须先有水</li></ul><p><strong>答案</strong>：A、B、C。</p><p><strong>解析</strong>：可燃物、氧化剂和引火源是常用的燃烧三要素。更完整的燃烧四面体还把链式反应作为条件之一。水不是燃烧发生的必要条件，某些火灾还不能用水直接处置。</p><p><strong>关联</strong>：<a href="/theory/03-combustion-fire">燃烧和火灾基础知识</a>。</p><h3 id="题卡-t04-·-单选题-·-l2-·-原创训练题" tabindex="-1">题卡 T04 · 单选题 · L2 · 原创训练题 <a class="header-anchor" href="#题卡-t04-·-单选题-·-l2-·-原创训练题" aria-label="Permalink to &quot;题卡 T04 · 单选题 · L2 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：厨房油锅内动植物油脂燃烧，按燃烧对象通常属于：</p><ul><li>A. A 类火灾</li><li>B. C 类火灾</li><li>C. E 类火灾</li><li>D. F 类火灾</li></ul><p><strong>答案</strong>：D。</p><p><strong>解析</strong>：F 类是烹饪器具内烹饪物火灾，典型对象是动植物油脂。A 类是一般固体，C 类是气体，E 类是带电火灾。处置油锅时严禁直接泼水，灭火器材应看产品铭牌和现场预案。</p><p><strong>依据</strong>：GB/T 4968《火灾分类》；<a href="/theory/07-initial-fire">初起火灾处置</a>。</p><h2 id="_3-建筑、电气和设施" tabindex="-1">3. 建筑、电气和设施 <a class="header-anchor" href="#_3-建筑、电气和设施" aria-label="Permalink to &quot;3. 建筑、电气和设施&quot;">​</a></h2><h3 id="题卡-t05-·-单选题-·-l2-·-原创训练题" tabindex="-1">题卡 T05 · 单选题 · L2 · 原创训练题 <a class="header-anchor" href="#题卡-t05-·-单选题-·-l2-·-原创训练题" aria-label="Permalink to &quot;题卡 T05 · 单选题 · L2 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：关于 GB 55037-2022《建筑防火通用规范》，下列说法正确的是：</p><ul><li>A. 自 2023 年 6 月 1 日起实施，属于强制性工程建设规范</li><li>B. 发布后 GB 50016 全部废止</li><li>C. 只适用于消防控制室，不涉及建筑防火</li><li>D. 与其他工程建设标准不一致时，仍以旧标准为准</li></ul><p><strong>答案</strong>：A。</p><p><strong>解析</strong>：GB 55037-2022 自 2023-06-01 起实施，全文为强制性工程建设规范。发布公告明确废止的是部分相关标准的强制性条文，不能说 GB 50016 全部废止；标准冲突时应按通用规范及现行公告核验。</p><p><strong>依据</strong>：<a href="https://www.gov.cn/zhengce/zhengceku/2023-01/30/content_5739161.htm" target="_blank" rel="noreferrer">住房和城乡建设部发布公告</a>；<a href="/theory/09-laws-standards">法规与标准</a>。</p><h3 id="题卡-t06-·-计算题-·-l1-·-原创训练题" tabindex="-1">题卡 T06 · 计算题 · L1 · 原创训练题 <a class="header-anchor" href="#题卡-t06-·-计算题-·-l1-·-原创训练题" aria-label="Permalink to &quot;题卡 T06 · 计算题 · L1 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：某单相设备额定电压约为 220 V、功率为 2 kW，按 <code>P=UI</code> 粗略计算额定电流约为多少？</p><p><strong>答案</strong>：约 9.1 A。</p><p><strong>解析</strong>：<code>I=P/U=2000÷220≈9.1 A</code>。这是理解公式的教学示例，不是断路器选型结论。实际选型还要考虑功率因数、启动电流、线路敷设、环境和设备说明书。</p><p><strong>关联</strong>：<a href="/theory/05-electrical-fire">电气消防基础知识</a>。</p><h2 id="_4-初起处置" tabindex="-1">4. 初起处置 <a class="header-anchor" href="#_4-初起处置" aria-label="Permalink to &quot;4. 初起处置&quot;">​</a></h2><h3 id="题卡-t07-·-场景题-·-l2-·-原创训练题" tabindex="-1">题卡 T07 · 场景题 · L2 · 原创训练题 <a class="header-anchor" href="#题卡-t07-·-场景题-·-l2-·-原创训练题" aria-label="Permalink to &quot;题卡 T07 · 场景题 · L2 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：发现配电箱冒烟并有火花，现场人员想立即用水冲灭。最符合安全原则的处置是：</p><ul><li>A. 立即泼水，火小就可以处理</li><li>B. 先报警、保持安全距离，按授权断电并使用适配带电火灾的器材</li><li>C. 打开柜门观察后再决定</li><li>D. 先拔掉几根线路让报警停止</li></ul><p><strong>答案</strong>：B。</p><p><strong>解析</strong>：配电箱可能带电。应先报警、隔离危险并按授权断电，灭火器材按带电火灾适用范围和产品铭牌选择。不能用水直接喷射带电设备，也不能拔线或短接掩盖故障。</p><p><strong>安全提示</strong>：未经培训和授权，不自行打开、拆装或带电处理电气设备。</p><p><strong>关联</strong>：<a href="/theory/07-initial-fire">初起火灾处置</a>、<a href="/theory/10-safety-health">安全生产</a>。</p><h2 id="_5-剩余理论模块补充题卡" tabindex="-1">5. 剩余理论模块补充题卡 <a class="header-anchor" href="#_5-剩余理论模块补充题卡" aria-label="Permalink to &quot;5. 剩余理论模块补充题卡&quot;">​</a></h2><h3 id="题卡-t15-·-多选题-·-l2-·-原创训练题" tabindex="-1">题卡 T15 · 多选题 · L2 · 原创训练题 <a class="header-anchor" href="#题卡-t15-·-多选题-·-l2-·-原创训练题" aria-label="Permalink to &quot;题卡 T15 · 多选题 · L2 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：发现设备长期屏蔽或故障未修复时，符合职业道德和岗位要求的做法包括：</p><ul><li>A. 如实记录设备、时间和影响范围</li><li>B. 按制度报告并落实临时防护</li><li>C. 为了不影响值班观感，删除历史记录</li><li>D. 维修后复测并确认恢复</li></ul><p><strong>答案</strong>：A、B、D。</p><p><strong>解析</strong>：职业道德要落实为如实、守规、负责和复核。屏蔽或故障不是“提示消失”就算处理完成，必须留下记录、报告影响并跟踪恢复。</p><p><strong>易错点</strong>：把消音、屏蔽或删除记录当成排除故障。</p><p><strong>关联</strong>：<a href="/theory/01-professional-ethics">职业道德</a>、<a href="/theory/02-fire-service-overview">消防工作概述</a>。</p><h3 id="题卡-t16-·-单选题-·-l2-·-原创训练题" tabindex="-1">题卡 T16 · 单选题 · L2 · 原创训练题 <a class="header-anchor" href="#题卡-t16-·-单选题-·-l2-·-原创训练题" aria-label="Permalink to &quot;题卡 T16 · 单选题 · L2 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：下列哪项最能体现“值班监控、维护保养、检测维修”的区别？</p><ul><li>A. 三者都只是查看控制器画面</li><li>B. 值班监控重在持续观察和报告，保养重在保持状态，检测维修重在测试判定、处理和复测</li><li>C. 做过一次检测即可不再值班</li><li>D. 保养可以代替故障维修</li></ul><p><strong>答案</strong>：B。</p><p><strong>解析</strong>：三类工作都服务于设施可靠运行，但任务目的和证据不同。检测维修方向学习者尤其要区分“看见正常”与“完成检测判定”。</p><p><strong>关联</strong>：<a href="/theory/02-fire-service-overview">消防工作概述</a>、<a href="/skill-roadmap">技能路线图</a>。</p><h3 id="题卡-t17-·-场景题-·-l2-·-原创训练题" tabindex="-1">题卡 T17 · 场景题 · L2 · 原创训练题 <a class="header-anchor" href="#题卡-t17-·-场景题-·-l2-·-原创训练题" aria-label="Permalink to &quot;题卡 T17 · 场景题 · L2 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：初起火灾火焰暂时变小，但现场烟气增大、撤退路线变差。此时应：</p><ul><li>A. 继续靠近，直到完全没有火焰</li><li>B. 立即撤离危险区域，报警、警戒并等待专业处置</li><li>C. 用湿毛巾后继续深入</li><li>D. 先清理现场再报告</li></ul><p><strong>答案</strong>：B。</p><p><strong>解析</strong>：能见度、烟气毒性和撤退条件比“火焰大小”更重要。灭火器训练不等于进入浓烟高温区域的授权，湿毛巾也不能提供可靠的有毒气体防护。</p><p><strong>关联</strong>：<a href="/theory/07-initial-fire">初起火灾处置</a>。</p><h3 id="题卡-t18-·-单选题-·-l2-·-原创训练题" tabindex="-1">题卡 T18 · 单选题 · L2 · 原创训练题 <a class="header-anchor" href="#题卡-t18-·-单选题-·-l2-·-原创训练题" aria-label="Permalink to &quot;题卡 T18 · 单选题 · L2 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：消防控制室图形显示装置显示正常，但现场设备反馈异常，较合理的首步是：</p><ul><li>A. 删除历史记录并重启电脑</li><li>B. 记录差异，分别核查控制器、通信链路、显示终端和现场设备</li><li>C. 直接判定现场设备全部失效</li><li>D. 拔掉通信线重新插入</li></ul><p><strong>答案</strong>：B。</p><p><strong>解析</strong>：显示终端只是信息链路的一环。应保留事实，区分主机、通信、图形显示和现场设备问题，不能通过删除记录或随意拔插来“修复”。</p><p><strong>关联</strong>：<a href="/theory/08-computer">计算机基础</a>、<a href="/skill/alarm-system">报警系统项目卡</a>。</p><h3 id="题卡-t19-·-多选题-·-l2-·-原创训练题" tabindex="-1">题卡 T19 · 多选题 · L2 · 原创训练题 <a class="header-anchor" href="#题卡-t19-·-多选题-·-l2-·-原创训练题" aria-label="Permalink to &quot;题卡 T19 · 多选题 · L2 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：涉及消防设施电气维修或高处、机械作业时，作业前应重点确认：</p><ul><li>A. 任务和授权范围</li><li>B. 停电、验电、隔离、监护及误启动防护</li><li>C. 工具、仪表和个人防护用品状态</li><li>D. 为节省时间跳过恢复检查</li></ul><p><strong>答案</strong>：A、B、C。</p><p><strong>解析</strong>：安全作业不仅是“断电”，还要控制残余能量、误送电、机械运动、高处坠落和现场人员风险。作业结束必须恢复防护、设备状态并记录。</p><p><strong>关联</strong>：<a href="/theory/10-safety-health">安全生产与职业健康</a>、<a href="/skill/alarm-system">报警系统项目卡</a>。</p><h2 id="_13-建筑防火" tabindex="-1">13. 建筑防火 <a class="header-anchor" href="#_13-建筑防火" aria-label="Permalink to &quot;13. 建筑防火&quot;">​</a></h2><h3 id="题卡-t38-·-单选题-·-l1-·-原创训练题" tabindex="-1">题卡 T38 · 单选题 · L1 · 原创训练题 <a class="header-anchor" href="#题卡-t38-·-单选题-·-l1-·-原创训练题" aria-label="Permalink to &quot;题卡 T38 · 单选题 · L1 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：下列概念与主要对象对应正确的是：</p><ul><li>A. 防火间距——同一建筑内部两个房间之间的距离</li><li>B. 耐火极限——整栋建筑的一级、二级分级</li><li>C. 防火分区——建筑内部限制火焰和火势扩大的区域边界</li><li>D. 防烟分区——单个构件在标准试验中保持承载能力的时间</li></ul><p><strong>答案</strong>：C。</p><p><strong>解析</strong>：防火分区关注建筑内部的火势边界；防烟分区关注烟气扩散控制；防火间距关注相邻建筑之间的空间距离；耐火极限关注具体构件在规定试验条件下保持相关性能的时间。一级、二级、三级、四级属于耐火等级的分级框架，是建筑整体耐火能力的概念。</p><p><strong>易错点</strong>：看到“分区”就把防火分区和防烟分区混为一谈，或者把“耐火等级”和“耐火极限”当成同一个单位。</p><p><strong>关联</strong>：<a href="/theory/04-building-fire">建筑防火基础知识</a>、<a href="/glossary">核心术语表</a>。</p><h3 id="题卡-t39-·-场景题-·-l3-·-原创训练题" tabindex="-1">题卡 T39 · 场景题 · L3 · 原创训练题 <a class="header-anchor" href="#题卡-t39-·-场景题-·-l3-·-原创训练题" aria-label="Permalink to &quot;题卡 T39 · 场景题 · L3 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：某学习者说：“一扇防火门的耐火极限达到规定时间，所以这栋建筑就是一级耐火等级建筑。”下列判断最恰当的是：</p><ul><li>A. 正确，建筑耐火等级只由防火门决定</li><li>B. 正确，只要防火门耐火极限高，其他构件可以不看</li><li>C. 不正确，耐火极限针对具体构件，耐火等级要综合建筑主要构件和建筑条件判断</li><li>D. 不正确，因为建筑没有耐火等级，只有防火分区</li></ul><p><strong>答案</strong>：C。</p><p><strong>解析</strong>：防火门只是建筑防火分隔中的一个构件。耐火极限描述具体构件或构件组合在规定试验条件下保持承载、完整或隔热性能的时间；耐火等级则是对整栋建筑耐火能力的分级，通常需要结合墙、柱、梁、楼板、屋顶承重构件及建筑用途、高度等条件判断。不能由一个构件反推整栋建筑等级。</p><p><strong>易错点</strong>：把“构件性能时间”当成“建筑整体等级”，或者只记住“一级最高”却不知道等级由什么综合形成。</p><p><strong>关联</strong>：<a href="/theory/04-building-fire">建筑防火基础知识</a>、<a href="/course-companion">综合学习课</a>。</p><h3 id="题卡-t20-·-单选题-·-l2-·-原创训练题" tabindex="-1">题卡 T20 · 单选题 · L2 · 原创训练题 <a class="header-anchor" href="#题卡-t20-·-单选题-·-l2-·-原创训练题" aria-label="Permalink to &quot;题卡 T20 · 单选题 · L2 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：建筑内一道防火分隔设施处于关闭状态，但其闭合器损坏、无法可靠自行关闭。对此判断最恰当的是：</p><ul><li>A. 门扇外观完整，所以可以视为正常</li><li>B. 只要控制室没有报警，就不需要处理</li><li>C. 应记录故障并按制度报告、维修和复核，不能只看外观</li><li>D. 直接拆除闭合器，避免门扇误动作</li></ul><p><strong>答案</strong>：C。</p><p><strong>解析</strong>：防火门、防火卷帘、防火阀等设施的作用不仅是“看起来存在”，还要在设计条件下完成分隔或阻断。闭合、启闭、反馈和联动条件出现异常时，应保留现场状态、报告影响并安排有授权的维修与复测；不能用删除报警或拆除部件代替处理。</p><p><strong>关联</strong>：<a href="/theory/04-building-fire">建筑防火基础知识</a>、<a href="/skill/other-facilities">其他消防设施项目卡</a>。</p><h3 id="题卡-t21-·-场景题-·-l3-·-原创训练题" tabindex="-1">题卡 T21 · 场景题 · L3 · 原创训练题 <a class="header-anchor" href="#题卡-t21-·-场景题-·-l3-·-原创训练题" aria-label="Permalink to &quot;题卡 T21 · 场景题 · L3 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：疏散走道堆放物品，导致出口前有效通行空间明显变窄。作为发现问题的工作人员，首要做法是：</p><ul><li>A. 拍照后等下次巡查再处理</li><li>B. 在确保自身安全的前提下报告并按单位制度组织清理或升级处置</li><li>C. 把物品移到防火门前</li><li>D. 关闭出口，防止人员使用</li></ul><p><strong>答案</strong>：B。</p><p><strong>解析</strong>：疏散通道和安全出口关系到人员逃生，不能把占用问题当作普通卫生问题。处置要遵循现场安全、岗位授权和单位制度，形成问题、影响、报告和整改复核记录；不得通过封闭出口制造新的风险。</p><p><strong>依据</strong>：<a href="/theory/09-laws-standards">法律法规与技术标准</a>、<a href="/sources">权威依据与版本边界</a>。</p><h2 id="_14-电气消防" tabindex="-1">14. 电气消防 <a class="header-anchor" href="#_14-电气消防" aria-label="Permalink to &quot;14. 电气消防&quot;">​</a></h2><h3 id="题卡-t22-·-单选题-·-l2-·-原创训练题" tabindex="-1">题卡 T22 · 单选题 · L2 · 原创训练题 <a class="header-anchor" href="#题卡-t22-·-单选题-·-l2-·-原创训练题" aria-label="Permalink to &quot;题卡 T22 · 单选题 · L2 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：维修消防设施控制回路前，已执行断电操作。下列做法仍然必要的是：</p><ul><li>A. 直接拆线，节省操作时间</li><li>B. 验电、隔离可能的电源和残余能量，并落实防误送电措施</li><li>C. 只观察控制器是否黑屏</li><li>D. 先短接线路确认故障是否消失</li></ul><p><strong>答案</strong>：B。</p><p><strong>解析</strong>：断电不能自动证明作业点无电，也不能消除备用电源、回路串电或误送电风险。必须按单位制度和作业规程完成验电、隔离、挂牌或锁定、监护等步骤；具体要求取决于作业对象和现场授权。</p><p><strong>关联</strong>：<a href="/theory/05-electrical-fire">电气消防基础知识</a>、<a href="/theory/10-safety-health">安全生产与职业健康</a>。</p><h2 id="_15-消防设施" tabindex="-1">15. 消防设施 <a class="header-anchor" href="#_15-消防设施" aria-label="Permalink to &quot;15. 消防设施&quot;">​</a></h2><h3 id="题卡-t23-·-单选题-·-l2-·-原创训练题" tabindex="-1">题卡 T23 · 单选题 · L2 · 原创训练题 <a class="header-anchor" href="#题卡-t23-·-单选题-·-l2-·-原创训练题" aria-label="Permalink to &quot;题卡 T23 · 单选题 · L2 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：消防设施检测中，控制器出现“有输出”显示，但现场执行机构没有完成预期动作。此时最合理的判断是：</p><ul><li>A. 只要控制器显示正常，就可判定系统合格</li><li>B. 应继续核对现场电源、线路、执行机构和动作反馈，不能跳过现场结果</li><li>C. 立即复位并删除记录</li><li>D. 直接更换控制器</li></ul><p><strong>答案</strong>：B。</p><p><strong>解析</strong>：控制器输出显示只是信号链中的一个环节，不能替代现场动作和反馈确认。检测应区分输入、控制输出、现场动作、反馈和恢复；发现不一致时，先记录事实，再按方案和授权范围排查。</p><p><strong>关联</strong>：<a href="/theory/06-fire-facilities">消防设施基础知识</a>、<a href="/skill/05-detection">设施检测</a>。</p><h3 id="题卡-t24-·-场景题-·-l3-·-原创训练题" tabindex="-1">题卡 T24 · 场景题 · L3 · 原创训练题 <a class="header-anchor" href="#题卡-t24-·-场景题-·-l3-·-原创训练题" aria-label="Permalink to &quot;题卡 T24 · 场景题 · L3 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：自动喷水灭火系统末端试水装置有水流出，但控制器没有收到相应反馈。最稳妥的首步是：</p><ul><li>A. 认定整个喷淋系统供水能力不足</li><li>B. 记录试验条件，分别核对水流信号、压力开关/水流指示器、线路和控制器输入</li><li>C. 关闭报警阀组，避免继续报警</li><li>D. 直接调大系统压力</li></ul><p><strong>答案</strong>：B。</p><p><strong>解析</strong>：末端试水有水流，只能说明该试验点发生了放水现象，不能单独推出全系统供水能力或全部联动功能。应按设计、验收/维护依据和设备说明书核对信号链，未经授权不得擅自改变系统压力或关闭保护设施。</p><p><strong>关联</strong>：<a href="/skill/water-system">水系统设备项目卡</a>、<a href="/skill/05-detection">设施检测</a>。</p><h2 id="_16-计算机与记录" tabindex="-1">16. 计算机与记录 <a class="header-anchor" href="#_16-计算机与记录" aria-label="Permalink to &quot;16. 计算机与记录&quot;">​</a></h2><h3 id="题卡-t25-·-单选题-·-l2-·-原创训练题" tabindex="-1">题卡 T25 · 单选题 · L2 · 原创训练题 <a class="header-anchor" href="#题卡-t25-·-单选题-·-l2-·-原创训练题" aria-label="Permalink to &quot;题卡 T25 · 单选题 · L2 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：发现图形显示装置与控制器记录时间不一致时，最合适的处理是：</p><ul><li>A. 直接修改历史记录，使两边看起来一致</li><li>B. 保留原始记录，记录差异并按权限和制度核查时钟、通信及日志来源</li><li>C. 删除时间较早的一侧记录</li><li>D. 重启所有设备后不再记录</li></ul><p><strong>答案</strong>：B。</p><p><strong>解析</strong>：记录的价值在于可追溯，不能为“整齐”而篡改或删除原始信息。时间差异可能与设备时钟、通信延迟、日志来源或权限设置有关，应保留事实、报告异常并由授权人员核查。</p><p><strong>关联</strong>：<a href="/theory/08-computer">计算机基础知识</a>、<a href="/skill/01-monitoring">设施监控</a>。</p><h2 id="_17-法律法规与技术标准" tabindex="-1">17. 法律法规与技术标准 <a class="header-anchor" href="#_17-法律法规与技术标准" aria-label="Permalink to &quot;17. 法律法规与技术标准&quot;">​</a></h2><h3 id="题卡-t26-·-单选题-·-l2-·-原创训练题" tabindex="-1">题卡 T26 · 单选题 · L2 · 原创训练题 <a class="header-anchor" href="#题卡-t26-·-单选题-·-l2-·-原创训练题" aria-label="Permalink to &quot;题卡 T26 · 单选题 · L2 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：题目要求判断某消防设施“是否必须保持可用”，首先应优先确认：</p><ul><li>A. 网络口诀是否这样说</li><li>B. 设施的法律/标准要求、工程对象、使用阶段和现场制度</li><li>C. 某品牌宣传页是否这样写</li><li>D. 其他建筑的做法</li></ul><p><strong>答案</strong>：B。</p><p><strong>解析</strong>：设施要求与建筑用途、设计条件、使用阶段和适用标准有关。法律法规、工程建设规范、专业标准、单位制度和设备说明书解决的问题不同，不能用单一来源替代适用性判断。</p><p><strong>关联</strong>：<a href="/theory/09-laws-standards">法律法规与技术标准</a>、<a href="/sources">权威依据与版本边界</a>。</p><h2 id="_18-安全生产与职业健康" tabindex="-1">18. 安全生产与职业健康 <a class="header-anchor" href="#_18-安全生产与职业健康" aria-label="Permalink to &quot;18. 安全生产与职业健康&quot;">​</a></h2><h3 id="题卡-t27-·-场景题-·-l3-·-原创训练题" tabindex="-1">题卡 T27 · 场景题 · L3 · 原创训练题 <a class="header-anchor" href="#题卡-t27-·-场景题-·-l3-·-原创训练题" aria-label="Permalink to &quot;题卡 T27 · 场景题 · L3 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：维修人员准备在消防泵附近进行检修，现场仍可能自动启动设备，且没有设置监护人。应如何处理？</p><ul><li>A. 先快速拆下部件，动作越快越安全</li><li>B. 暂停作业，确认授权、停机/隔离、防误启动和监护条件后再开始</li><li>C. 让无关人员站远一点即可</li><li>D. 关闭控制器所有电源并离开</li></ul><p><strong>答案</strong>：B。</p><p><strong>解析</strong>：消防泵可能存在自动启动、机械运动和电气危险。作业前要根据任务落实授权、隔离、误启动防护、监护和恢复安排；不能用“快一点”或简单关闭某个电源替代完整的安全控制。</p><p><strong>关联</strong>：<a href="/theory/10-safety-health">安全生产与职业健康</a>、<a href="/skill/water-system">水系统设备项目卡</a>。</p><h2 id="_19-阅读复习方法" tabindex="-1">19. 阅读复习方法 <a class="header-anchor" href="#_19-阅读复习方法" aria-label="Permalink to &quot;19. 阅读复习方法&quot;">​</a></h2><p>每看完一张题卡，按以下顺序复习：</p><ol><li>先看正确答案；</li><li>阅读解析，确认错误选项错在哪里；</li><li>打开关联知识页，补充原理；</li><li>说出这道题在技能操作中的对应场景；</li><li>继续阅读下一张，不需要输入或提交任何内容。</li></ol><blockquote><p>本页题目均标记为“原创训练题”，不是官方真题或历年原题。训练题不等同于实际考试。</p></blockquote><h2 id="_6-消防设施信号链" tabindex="-1">6. 消防设施信号链 <a class="header-anchor" href="#_6-消防设施信号链" aria-label="Permalink to &quot;6. 消防设施信号链&quot;">​</a></h2><h3 id="题卡-t08-·-单选题-·-l1-·-原创训练题" tabindex="-1">题卡 T08 · 单选题 · L1 · 原创训练题 <a class="header-anchor" href="#题卡-t08-·-单选题-·-l1-·-原创训练题" aria-label="Permalink to &quot;题卡 T08 · 单选题 · L1 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：火灾探测器动作后，控制器显示火灾报警；随后现场设备动作并返回动作状态。下列顺序最符合基本信号链的是：</p><ul><li>A. 反馈 → 探测 → 复位 → 报警</li><li>B. 输入/触发 → 控制器显示 → 联动输出 → 现场动作/反馈</li><li>C. 复位 → 输入/触发 → 现场动作 → 报警</li><li>D. 现场动作 → 探测 → 控制器显示 → 断电</li></ul><p><strong>答案</strong>：B。</p><p><strong>解析</strong>：探测器、手动火灾报警按钮等属于输入端；控制器负责接收、显示和按设计逻辑处理；联动控制回路向现场设备发出控制；动作、运行或故障状态再以反馈形式返回。报警、联动、反馈、复位不是同一个概念。</p><p><strong>易错点</strong>：把“有反馈”理解成“已经复位”，或把联动输出当作现场设备动作本身。</p><p><strong>关联</strong>：<a href="/theory/06-fire-facilities">消防设施基础知识</a>、<a href="/glossary">核心术语表</a>。</p><h3 id="题卡-t09-·-判断题-·-l2-·-原创训练题" tabindex="-1">题卡 T09 · 判断题 · L2 · 原创训练题 <a class="header-anchor" href="#题卡-t09-·-判断题-·-l2-·-原创训练题" aria-label="Permalink to &quot;题卡 T09 · 判断题 · L2 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：控制器消音后，火灾报警信息已经被排除，可以直接恢复正常监视。</p><p><strong>答案</strong>：错误。</p><p><strong>解析</strong>：消音只改变声响提示状态，不等于报警原因消失，也不等于系统复位。仍需按预案核实、报告、处置，并在满足条件时复位和确认系统状态。</p><p><strong>依据</strong>：<a href="/skill/01-monitoring">设施监控</a>。</p><h2 id="_7-设备状态与故障边界" tabindex="-1">7. 设备状态与故障边界 <a class="header-anchor" href="#_7-设备状态与故障边界" aria-label="Permalink to &quot;7. 设备状态与故障边界&quot;">​</a></h2><h3 id="题卡-t10-·-多选题-·-l2-·-原创训练题" tabindex="-1">题卡 T10 · 多选题 · L2 · 原创训练题 <a class="header-anchor" href="#题卡-t10-·-多选题-·-l2-·-原创训练题" aria-label="Permalink to &quot;题卡 T10 · 多选题 · L2 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：发现控制器显示故障时，较合适的首轮信息记录包括：</p><ul><li>A. 故障类别</li><li>B. 地址、回路或设备位置</li><li>C. 出现时间及是否反复出现</li><li>D. 为了消除提示而直接拔掉设备</li></ul><p><strong>答案</strong>：A、B、C。</p><p><strong>解析</strong>：故障排查首先要保留可追溯信息，避免凭感觉拆改。地址、时间、类别和伴随现象有助于判断是设备、线路、供电还是通信问题。拔掉设备可能造成保护缺口，不能作为正常排故手段。</p><p><strong>关联</strong>：<a href="/skill/04-repair">设施维修</a>。</p><h2 id="_8-初起火灾与人员安全" tabindex="-1">8. 初起火灾与人员安全 <a class="header-anchor" href="#_8-初起火灾与人员安全" aria-label="Permalink to &quot;8. 初起火灾与人员安全&quot;">​</a></h2><h3 id="题卡-t11-·-场景题-·-l3-·-原创训练题" tabindex="-1">题卡 T11 · 场景题 · L3 · 原创训练题 <a class="header-anchor" href="#题卡-t11-·-场景题-·-l3-·-原创训练题" aria-label="Permalink to &quot;题卡 T11 · 场景题 · L3 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：走廊出现烟气且能见度快速下降，附近人员想返回房间取物。最符合安全原则的是：</p><ul><li>A. 立即返回，动作快即可</li><li>B. 先报警并沿安全疏散方向撤离，不为取物返回烟气区域</li><li>C. 用湿毛巾后即可穿过浓烟</li><li>D. 关闭所有防火门后再返回</li></ul><p><strong>答案</strong>：B。</p><p><strong>解析</strong>：人员安全优先。烟气具有毒性、热危害和能见度影响，湿毛巾不能保证过滤有毒气体；在烟气环境中不要把任何简易措施当作安全通行许可。报警、疏散和服从现场组织是首要行动。</p><p><strong>安全提示</strong>：本题是安全原则训练，不替代具体建筑的疏散预案。</p><p><strong>关联</strong>：<a href="/theory/07-initial-fire">初起火灾处置</a>、<a href="/theory/10-safety-health">安全生产与职业健康</a>。</p><h2 id="_9-法规与标准版本" tabindex="-1">9. 法规与标准版本 <a class="header-anchor" href="#_9-法规与标准版本" aria-label="Permalink to &quot;9. 法规与标准版本&quot;">​</a></h2><h3 id="题卡-t12-·-单选题-·-l2-·-原创训练题" tabindex="-1">题卡 T12 · 单选题 · L2 · 原创训练题 <a class="header-anchor" href="#题卡-t12-·-单选题-·-l2-·-原创训练题" aria-label="Permalink to &quot;题卡 T12 · 单选题 · L2 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：学习建筑消防设施时，遇到旧资料与现行强制性工程建设规范表述不一致，较稳妥的做法是：</p><ul><li>A. 以传播最广的口诀为准</li><li>B. 只看培训群转发截图</li><li>C. 回查现行规范、发布公告、设计文件和设备说明书的适用边界</li><li>D. 直接删除旧资料涉及的全部内容</li></ul><p><strong>答案</strong>：C。</p><p><strong>解析</strong>：标准适用需要结合发布日期、实施日期、废止或修改范围、工程对象和设备条件判断。不能用单一口诀替代标准核验，也不能因为存在旧资料就把相关知识整体删除。</p><p><strong>依据</strong>：<a href="/sources">权威依据与版本边界</a>、<a href="/theory/09-laws-standards">法律法规与技术标准</a>。</p><h2 id="_10-计算机与记录" tabindex="-1">10. 计算机与记录 <a class="header-anchor" href="#_10-计算机与记录" aria-label="Permalink to &quot;10. 计算机与记录&quot;">​</a></h2><h3 id="题卡-t13-·-单选题-·-l1-·-原创训练题" tabindex="-1">题卡 T13 · 单选题 · L1 · 原创训练题 <a class="header-anchor" href="#题卡-t13-·-单选题-·-l1-·-原创训练题" aria-label="Permalink to &quot;题卡 T13 · 单选题 · L1 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：消防控制室值班记录的首要价值是：</p><ul><li>A. 只用于填满表格</li><li>B. 形成事件、操作、反馈、异常和报告的可追溯记录</li><li>C. 代替设备维修</li><li>D. 代替现场巡查</li></ul><p><strong>答案</strong>：B。</p><p><strong>解析</strong>：记录要真实、及时、可追溯，通常应包含时间、对象、现象、采取的措施、反馈结果、恢复状态和报告对象。记录不能代替操作、维修或巡查本身。</p><p><strong>关联</strong>：<a href="/theory/08-computer">计算机基础知识</a>、<a href="/skill/01-monitoring">设施监控</a>。</p><h2 id="_11-安全生产与职业健康" tabindex="-1">11. 安全生产与职业健康 <a class="header-anchor" href="#_11-安全生产与职业健康" aria-label="Permalink to &quot;11. 安全生产与职业健康&quot;">​</a></h2><h3 id="题卡-t14-·-判断题-·-l2-·-原创训练题" tabindex="-1">题卡 T14 · 判断题 · L2 · 原创训练题 <a class="header-anchor" href="#题卡-t14-·-判断题-·-l2-·-原创训练题" aria-label="Permalink to &quot;题卡 T14 · 判断题 · L2 · 原创训练题&quot;">​</a></h3><p><strong>题干</strong>：只要设备已经断电，就可以立即拆卸电气部件，不需要验电、隔离和监护。</p><p><strong>答案</strong>：错误。</p><p><strong>解析</strong>：断电是安全措施的一部分，不等于已经完成验电、挂牌、隔离、释放残余能量和落实监护。具体作业应由受训、授权人员按单位制度和作业规程实施。</p><p><strong>关联</strong>：<a href="/theory/10-safety-health">安全生产与职业健康</a>。</p><h2 id="_19-理论十章-l3-综合场景补充" tabindex="-1">19. 理论十章 L3 综合场景补充 <a class="header-anchor" href="#_19-理论十章-l3-综合场景补充" aria-label="Permalink to &quot;19. 理论十章 L3 综合场景补充&quot;">​</a></h2><p>下面每张题卡都对应一个理论章节，并把理论知识连接到消防设施检测维修保养方向的实际判断。阅读时不要只记答案，要先说出“依据是什么、风险在哪里、下一步如何验证”。</p><h3 id="题卡-t28-·-场景题-·-l3-·-原创训练题-·-职业道德" tabindex="-1">题卡 T28 · 场景题 · L3 · 原创训练题 · 职业道德 <a class="header-anchor" href="#题卡-t28-·-场景题-·-l3-·-原创训练题-·-职业道德" aria-label="Permalink to &quot;题卡 T28 · 场景题 · L3 · 原创训练题 · 职业道德&quot;">​</a></h3><p><strong>场景</strong>：维修人员更换了一个报警模块，控制器暂时不再显示故障，但维修记录只写“已处理”，没有写更换对象、测试结果和恢复状态。</p><p><strong>答案</strong>：记录不完整，不能仅凭故障提示消失判定工作完成。</p><p><strong>解析</strong>：职业道德中的如实、负责和复核，要落实为可追溯记录。至少应补充设备地址或位置、故障现象、处理动作、复测结果、联动/反馈状态、恢复状态、时间和责任人员。故障提示消失只说明显示状态发生变化，不等于相关功能已经验证。</p><p><strong>关联技能</strong>：<a href="/skill/04-repair">设施维修</a>、<a href="/skill/05-detection">设施检测</a>。</p><h3 id="题卡-t29-·-场景题-·-l3-·-原创训练题-·-消防工作概述" tabindex="-1">题卡 T29 · 场景题 · L3 · 原创训练题 · 消防工作概述 <a class="header-anchor" href="#题卡-t29-·-场景题-·-l3-·-原创训练题-·-消防工作概述" aria-label="Permalink to &quot;题卡 T29 · 场景题 · L3 · 原创训练题 · 消防工作概述&quot;">​</a></h3><p><strong>场景</strong>：单位发现某区域消防设施长期处于故障状态，值班人员已多次口头提醒，但没有形成书面记录，也没有落实临时防护。</p><p><strong>答案</strong>：应立即记录并按制度报告，评估影响范围，落实临时防护和维修跟踪，不能只靠口头提醒。</p><p><strong>解析</strong>：单位对消防设施完好有效承担管理责任，岗位人员发现异常后要履行监控、报告和记录职责。操作员不能擅自作重大停用决定，但也不能因无权维修就不记录、不报告。</p><p><strong>关联技能</strong>：<a href="/skill/01-monitoring">设施监控</a>、<a href="/skill/03-maintenance">设施保养</a>、<a href="/skill/04-repair">设施维修</a>。</p><h3 id="题卡-t30-·-场景题-·-l3-·-原创训练题-·-燃烧和火灾" tabindex="-1">题卡 T30 · 场景题 · L3 · 原创训练题 · 燃烧和火灾 <a class="header-anchor" href="#题卡-t30-·-场景题-·-l3-·-原创训练题-·-燃烧和火灾" aria-label="Permalink to &quot;题卡 T30 · 场景题 · L3 · 原创训练题 · 燃烧和火灾&quot;">​</a></h3><p><strong>场景</strong>：配电柜附近出现焦糊味和少量烟雾，现场人员认为火势很小，可以直接打开柜门用水查看。</p><p><strong>答案</strong>：不能直接打开或用水处理；应报警、保持距离，按授权断电并由受训人员使用适配器材或等待专业处置。</p><p><strong>解析</strong>：电气火灾可能仍带电，焦糊味和烟雾还可能来自接触不良、过载、短路或电弧。燃烧类别判断要结合燃烧对象和带电状态，不能因为火焰小就忽视触电、复燃和烟气风险。</p><p><strong>关联技能</strong>：<a href="/theory/07-initial-fire">初起火灾处置</a>、<a href="/theory/05-electrical-fire">电气消防</a>。</p><h3 id="题卡-t31-·-场景题-·-l3-·-原创训练题-·-建筑防火" tabindex="-1">题卡 T31 · 场景题 · L3 · 原创训练题 · 建筑防火 <a class="header-anchor" href="#题卡-t31-·-场景题-·-l3-·-原创训练题-·-建筑防火" aria-label="Permalink to &quot;题卡 T31 · 场景题 · L3 · 原创训练题 · 建筑防火&quot;">​</a></h3><p><strong>场景</strong>：防火卷帘联动下降测试时，卷帘下方有货物，控制器显示已发出下降指令，但卷帘未完全到位。</p><p><strong>答案</strong>：应先保护人员并清除或报告障碍，区分控制输出、机械动作、到位状态和反馈，再按授权复测；不能只看控制器输出就判定合格。</p><p><strong>解析</strong>：建筑防火设施的价值在于形成分隔。卷帘下方障碍可能造成机械阻挡和防护失效，控制器有输出只代表信号链的一环。实际检测还要关注现场安全、卷帘位置、限位/反馈和恢复状态。</p><p><strong>关联技能</strong>：<a href="/skill/other-facilities">其他消防设施项目卡</a>、<a href="/skill/05-detection">设施检测</a>。</p><h3 id="题卡-t32-·-场景题-·-l3-·-原创训练题-·-电气消防" tabindex="-1">题卡 T32 · 场景题 · L3 · 原创训练题 · 电气消防 <a class="header-anchor" href="#题卡-t32-·-场景题-·-l3-·-原创训练题-·-电气消防" aria-label="Permalink to &quot;题卡 T32 · 场景题 · L3 · 原创训练题 · 电气消防&quot;">​</a></h3><p><strong>场景</strong>：消防控制器主电故障，备用电源指示正常。有人准备直接拆下蓄电池检查端子。</p><p><strong>答案</strong>：不能直接拆卸；应记录故障，确认授权、停电隔离、验电和防误送电措施，由有能力的人员按说明书和规程检查。</p><p><strong>解析</strong>：备用电源正常不代表可以忽略电气危险，蓄电池、充电回路和控制回路仍可能存在电压、短路和误动作风险。断电、验电、隔离和恢复检查是不同步骤，不能用“指示正常”替代。</p><p><strong>关联技能</strong>：<a href="/skill/04-repair">设施维修</a>、<a href="/theory/10-safety-health">安全生产与职业健康</a>。</p><h3 id="题卡-t33-·-场景题-·-l3-·-原创训练题-·-消防设施" tabindex="-1">题卡 T33 · 场景题 · L3 · 原创训练题 · 消防设施 <a class="header-anchor" href="#题卡-t33-·-场景题-·-l3-·-原创训练题-·-消防设施" aria-label="Permalink to &quot;题卡 T33 · 场景题 · L3 · 原创训练题 · 消防设施&quot;">​</a></h3><p><strong>场景</strong>：感烟探测器报警后，控制器显示火警，但联动风机没有启动。现场人员准备直接更换探测器。</p><p><strong>答案</strong>：不能直接更换探测器；应先记录地址和时间，区分探测输入、联动条件、控制输出、风机/风阀现场动作和反馈链路，再按授权排查。</p><p><strong>解析</strong>：报警输入正常不等于联动条件已经满足，也不等于输出、执行机构或反馈一定正常。直接更换探测器没有针对现象建立证据链，可能遗漏联动逻辑、控制方式、供电、线路或风机设备故障。</p><p><strong>关联技能</strong>：<a href="/theory/06-fire-facilities">消防设施基础知识</a>、<a href="/skill/04-repair">设施维修</a>、<a href="/skill/05-detection">设施检测</a>。</p><h3 id="题卡-t34-·-场景题-·-l3-·-原创训练题-·-初起火灾处置" tabindex="-1">题卡 T34 · 场景题 · L3 · 原创训练题 · 初起火灾处置 <a class="header-anchor" href="#题卡-t34-·-场景题-·-l3-·-原创训练题-·-初起火灾处置" aria-label="Permalink to &quot;题卡 T34 · 场景题 · L3 · 原创训练题 · 初起火灾处置&quot;">​</a></h3><p><strong>场景</strong>：灭火器扑灭了明火，但现场仍有大量烟气，附近人员想立即进入清理和搬动物品。</p><p><strong>答案</strong>：不能立即进入清理；应继续警戒、观察复燃风险、清点人员并保护现场，等待专业人员确认安全。</p><p><strong>解析</strong>：明火消失不代表温度、烟气、带电、复燃或结构风险消失。火灾处置结束还包括人员安全、现场保护和信息移交，不能把“看不见火”当成“现场已经安全”。</p><p><strong>关联技能</strong>：<a href="/theory/07-initial-fire">初起火灾处置</a>、<a href="/theory/10-safety-health">安全生产与职业健康</a>。</p><h3 id="题卡-t35-·-场景题-·-l3-·-原创训练题-·-计算机基础" tabindex="-1">题卡 T35 · 场景题 · L3 · 原创训练题 · 计算机基础 <a class="header-anchor" href="#题卡-t35-·-场景题-·-l3-·-原创训练题-·-计算机基础" aria-label="Permalink to &quot;题卡 T35 · 场景题 · L3 · 原创训练题 · 计算机基础&quot;">​</a></h3><p><strong>场景</strong>：图形显示装置显示某设备正常，但控制器历史记录显示该设备此前反复故障，现场巡查也发现反馈不稳定。</p><p><strong>答案</strong>：应保留历史记录，记录显示差异，分别核查控制器、通信链路、图形显示和现场设备，不能只相信当前画面。</p><p><strong>解析</strong>：图形显示是信息链路的一部分，当前界面正常可能是通信延迟、显示缓存、权限或设备状态变化造成的。记录和日志不能删除，判断要以多来源信息交叉核对，并通过授权检测确认。</p><p><strong>关联技能</strong>：<a href="/skill/01-monitoring">设施监控</a>、<a href="/skill/05-detection">设施检测</a>。</p><h3 id="题卡-t36-·-场景题-·-l3-·-原创训练题-·-法律法规与技术标准" tabindex="-1">题卡 T36 · 场景题 · L3 · 原创训练题 · 法律法规与技术标准 <a class="header-anchor" href="#题卡-t36-·-场景题-·-l3-·-原创训练题-·-法律法规与技术标准" aria-label="Permalink to &quot;题卡 T36 · 场景题 · L3 · 原创训练题 · 法律法规与技术标准&quot;">​</a></h3><p><strong>场景</strong>：某检测报告把施工验收时使用的压力和时间参数，直接写成所有建筑消防设施日常保养的统一合格阈值。</p><p><strong>答案</strong>：这种写法不严谨，应区分设计、施工验收、维护保养和检测场景，回查适用标准、方案、设备说明书和建筑实际条件。</p><p><strong>解析</strong>：不同文件解决的问题不同，验收参数不能自动外推为所有日常保养或检测结论。报告应写明检测对象、方法、依据、版本、原始结果、判定和限制条件，不得把来源不明的统一数字包装成标准要求。</p><p><strong>关联技能</strong>：<a href="/theory/09-laws-standards">法律法规与技术标准</a>、<a href="/skill/05-detection">设施检测</a>。</p><h3 id="题卡-t37-·-场景题-·-l3-·-原创训练题-·-安全生产与职业健康" tabindex="-1">题卡 T37 · 场景题 · L3 · 原创训练题 · 安全生产与职业健康 <a class="header-anchor" href="#题卡-t37-·-场景题-·-l3-·-原创训练题-·-安全生产与职业健康" aria-label="Permalink to &quot;题卡 T37 · 场景题 · L3 · 原创训练题 · 安全生产与职业健康&quot;">​</a></h3><p><strong>场景</strong>：检测风机和防火阀时，现场没有设置警戒区域，且有人可能进入风阀和卷帘运动范围。操作人员准备先启动设备再提醒周围人员。</p><p><strong>答案</strong>：应暂停操作，先确认授权、清场、警戒、监护和误启动防护，再按方案检测。</p><p><strong>解析</strong>：安全确认是操作前置条件，不是动作之后的补救。风机、风阀和卷帘可能产生机械运动，人员进入危险区域会造成伤害。检测必须同时满足人员安全、设备条件、控制方式和恢复安排。</p><p><strong>关联技能</strong>：<a href="/theory/10-safety-health">安全生产与职业健康</a>、<a href="/skill/05-detection">设施检测</a>。</p><h2 id="_20-十章覆盖检查" tabindex="-1">20. 十章覆盖检查 <a class="header-anchor" href="#_20-十章覆盖检查" aria-label="Permalink to &quot;20. 十章覆盖检查&quot;">​</a></h2><p>本页当前已按十个理论章节建立题卡入口：</p><table tabindex="0"><thead><tr><th>章节</th><th>题卡</th><th>学习目的</th></tr></thead><tbody><tr><td>1. 职业道德</td><td>T01、T15</td><td>区分方针、原则、守则和记录责任</td></tr><tr><td>2. 消防工作概述</td><td>T02、T16</td><td>理解单位责任与岗位边界</td></tr><tr><td>3. 燃烧和火灾</td><td>T03-T04</td><td>识别燃烧条件、火灾分类和禁忌</td></tr><tr><td>4. 建筑防火</td><td>T20-T21</td><td>判断防火分隔和疏散风险</td></tr><tr><td>5. 电气消防</td><td>T06、T22</td><td>理解公式和安全检修边界</td></tr><tr><td>6. 消防设施</td><td>T08-T10、T23-T24</td><td>理解输入、输出、动作、反馈和恢复</td></tr><tr><td>7. 初起火灾处置</td><td>T07、T11、T17</td><td>建立报警、疏散和撤退优先原则</td></tr><tr><td>8. 计算机基础</td><td>T13、T18、T25</td><td>保持日志、通信和记录可追溯</td></tr><tr><td>9. 法律法规与技术标准</td><td>T05、T12、T26</td><td>练习来源层级和版本适用判断</td></tr><tr><td>10. 安全生产与职业健康</td><td>T14、T19、T27、T37</td><td>识别隔离、监护、误启动和停止条件</td></tr></tbody></table><blockquote><p>这里的“覆盖”表示每章至少有可阅读的原创训练题，不表示题量等同于实际考试题库，也不代表官方真题。后续应继续按知识点增加 L1/L2/L3 题卡。</p></blockquote>',261)])])}const f=r(e,[["render",i]]);export{u as __pageData,f as default};
